ASTER_SEARCH_PROXY:
location = /_aster/rutube-search {
    limit_except GET { deny all; }
    proxy_pass https://rutube.ru/api/search/video/;
    proxy_ssl_server_name on;
    proxy_ssl_name rutube.ru;
    proxy_pass_request_headers off;
    proxy_set_header Host rutube.ru;
    proxy_set_header Accept application/json;
    proxy_set_header User-Agent "Mozilla/5.0 (compatible; AsterVideo/1.0)";
    proxy_hide_header Set-Cookie;
    proxy_connect_timeout 5s;
    proxy_read_timeout 15s;
}

ASTER_COMMENTS_PROXY:
location ~ "^/_aster/rutube-comments/(?<aster_video>[a-f0-9]{32})$" {
    if ($request_method != GET) { return 405; }
    if ($args !~ "^(?:comment_id=[0-9]{1,24}(?:&parent_id=[0-9]{1,24})?|parent_id=[0-9]{1,24})?$") { return 400; }
    rewrite ^ /api/v2/comments/video/$aster_video/?client=wdp&sort_by=date_added_desc&direction=earliest break;
    proxy_pass https://rutube.ru;
    proxy_ssl_server_name on;
    proxy_ssl_name rutube.ru;
    proxy_ssl_verify on;
    proxy_ssl_verify_depth 4;
    proxy_ssl_trusted_certificate /etc/ssl/certs/ca-certificates.crt;
    proxy_pass_request_headers off;
    proxy_pass_request_body off;
    proxy_set_header Host rutube.ru;
    proxy_set_header Accept application/json;
    proxy_set_header User-Agent "Mozilla/5.0";
    proxy_set_header Referer "https://rutube.ru/";
    proxy_set_header Content-Length "";
    proxy_hide_header Set-Cookie;
    proxy_hide_header Location;
    proxy_hide_header Cache-Control;
    proxy_cache off;
    proxy_redirect off;
    proxy_intercept_errors on;
    error_page 301 302 303 307 308 =502 @aster_comments_error;
    add_header Cache-Control "no-store" always;
    add_header X-Content-Type-Options nosniff always;
    proxy_connect_timeout 5s;
    proxy_read_timeout 15s;
}
location @aster_comments_error { return 502; }
location /_aster/rutube-comments/ { return 404; }

NORTHLINE_PROXY:
location ~ "^/_northline/mastodon/api/v1/accounts/[0-9]{1,20}$" {
    if ($request_method != GET) { return 405; }
    if ($args !~ "^$") { return 400; }
    rewrite ^/_northline/mastodon(/api/.*)$ $1 break;
    proxy_pass https://mastodon.ml;
